// Social Media Publisher: generated by `npm run bundle` from src/. Do not edit; edit src/ and rebuild.

// ---- src/core.js ----
/**
 * Shared pieces with no Google services in them: errors, ids, input checks and the platform list.
 */

const API_VERSION = '1.1.1';
const NAME_RE = /^[a-z0-9-]{1,40}$/;
const JOB_STATUSES = ['queued', 'running', 'done', 'failed', 'cancelled'];
const MAX_ATTEMPTS = 3;
// Each upload chunk is read from Drive and sent to the platform in one request.
// It must stay under Apps Script's 50 MB fetch limit and be a multiple of 256 KB.
let CHUNK_BYTES = 20 * 1024 * 1024;
// A worker run stops starting new work after this long, well inside Apps Script's 6 minute limit.
let WORK_BUDGET_MS = 4 * 60 * 1000;

class ApiError extends Error {
  constructor(code, message, details) {
    super(message);
    this.code = code;
    this.details = details;
  }
}

/** Every publishing platform. A new platform is one new file and one line here. */
function platforms_() {
  return { youtube: YouTube, instagram: Instagram, facebook: Facebook, linkedin: LinkedIn };
}

function adapterFor_(name) {
  const a = platforms_()[name];
  if (!a) throw new ApiError('invalid', `Unknown platform "${name}". Platforms: ${Object.keys(platforms_()).join(', ')}`);
  return a;
}

// ---------- input checks used by the adapters ----------

function optText_(v, field, max) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v !== 'string') throw new ApiError('invalid', `${field} must be text`);
  if (v.length > max) throw new ApiError('invalid', `${field} is ${v.length} characters; the limit is ${max}`);
  return v;
}

/** UTF-8 length of a string, the unit YouTube counts descriptions in. */
function utf8Bytes_(s) {
  let n = 0;
  for (const ch of s) {
    const c = ch.codePointAt(0);
    n += c < 0x80 ? 1 : c < 0x800 ? 2 : c < 0x10000 ? 3 : 4;
  }
  return n;
}

function optBool_(v, field) {
  if (v === undefined || v === null) return null;
  if (typeof v !== 'boolean') throw new ApiError('invalid', `${field} must be true or false`);
  return v;
}

/** A file the service reads: {"driveFileId": "..."}. */
function optFile_(v, field) {
  if (v === undefined || v === null) return null;
  if (!v || typeof v !== 'object' || typeof v.driveFileId !== 'string' || !v.driveFileId) {
    throw new ApiError('invalid', `${field} must look like {"driveFileId": "..."}`);
  }
  return { driveFileId: v.driveFileId };
}

function optFutureTime_(v, field, now) {
  if (v === undefined || v === null || v === '') return null;
  const d = new Date(v);
  if (typeof v !== 'string' || isNaN(d.getTime())) throw new ApiError('invalid', `${field} must be an ISO time like 2026-11-20T14:00:00Z`);
  if (d.getTime() < now.getTime() + 15 * 60 * 1000) throw new ApiError('invalid', `${field} must be at least 15 minutes in the future`);
  return d.toISOString();
}

// ---------- jobs ----------

function newJobId_(now, rand) {
  return `j-${now.toISOString().replace(/\D/g, '').slice(0, 12)}-${rand}`;
}

/** What callers see: everything except the adapter's private working state. */
function presentJob_(job) {
  const s = job.state || {};
  const out = {
    id: job.id, key: job.key || null, platform: job.platform, status: job.status, title: job.title,
    attempts: job.attempts || 0, notBefore: job.notBefore || null, createdAt: job.createdAt, updatedAt: job.updatedAt,
    caller: job.caller, result: job.result || null, error: job.error || null,
  };
  if (job.status === 'queued' || job.status === 'running') {
    out.progress = { step: s.step || null, uploadedBytes: s.offset || 0, totalBytes: s.size || null };
  }
  return out;
}

/** The oldest queued job that is allowed to run now. A job left "running" by a crashed run counts as queued after 10 minutes. */
function pickNextJob_(jobs, now) {
  const t = now.getTime();
  return jobs
    .filter((j) => (j.status === 'queued' && (!j.notBefore || new Date(j.notBefore).getTime() <= t))
      || (j.status === 'running' && new Date(j.updatedAt).getTime() < t - 10 * 60 * 1000))
    .sort((a, b) => (a.createdAt < b.createdAt ? -1 : 1))[0] || null;
}

/** Decides what happens to a job after a step throws. */
function afterError_(job, err, now) {
  const retry = err && err.details && err.details.retry;
  const message = String(err && err.message ? err.message : err);
  if (retry === 'quota') {
    // Daily quota resets at midnight Pacific time; try again in an hour rather than computing it exactly.
    return { status: 'queued', notBefore: new Date(now.getTime() + 60 * 60 * 1000).toISOString(), error: `Waiting for quota: ${message}` };
  }
  const attempts = (job.attempts || 0) + 1;
  if (retry === 'transient' && attempts < MAX_ATTEMPTS) {
    return { status: 'queued', attempts, notBefore: new Date(now.getTime() + 5 * 60 * 1000).toISOString(), error: `Will retry: ${message}` };
  }
  return { status: 'failed', attempts, error: message };
}

// ---- src/google.js ----
/**
 * Small helpers for calling Google REST APIs as the script owner (Drive and YouTube).
 */

function google_(method, url, opts) {
  const o = opts || {};
  const params = {
    method,
    muteHttpExceptions: true,
    headers: Object.assign({ Authorization: `Bearer ${url.includes('/youtube/') ? youTubeToken_() : ScriptApp.getOAuthToken()}` }, o.headers || {}),
  };
  if (o.json !== undefined) {
    params.contentType = 'application/json; charset=UTF-8';
    params.payload = JSON.stringify(o.json);
  } else if (o.payload !== undefined) {
    params.payload = o.payload;
    if (o.contentType) params.contentType = o.contentType;
  }
  return UrlFetchApp.fetch(url, params);
}

/** Calls an API and returns its JSON, or throws an ApiError that says whether a retry can help. */
function googleJson_(method, url, opts) {
  const r = google_(method, url, opts);
  const code = r.getResponseCode();
  if (code >= 200 && code < 300) {
    const text = r.getContentText();
    return text ? JSON.parse(text) : {};
  }
  throw upstreamError_(r);
}

function upstreamError_(r) {
  const code = r.getResponseCode();
  let reason = '';
  let message = '';
  try {
    const e = JSON.parse(r.getContentText()).error || {};
    reason = (e.errors && e.errors[0] && e.errors[0].reason) || e.status || '';
    message = e.message || '';
  } catch (err) {
    message = String(r.getContentText()).slice(0, 300);
  }
  let retry = false;
  if (['quotaExceeded', 'uploadLimitExceeded', 'dailyLimitExceeded'].includes(reason)) retry = 'quota';
  else if (code >= 500 || code === 429 || ['rateLimitExceeded', 'userRateLimitExceeded', 'backendError'].includes(reason)) retry = 'transient';
  return new ApiError('upstream', `Google answered ${code}${reason ? ` (${reason})` : ''}: ${message}`, { status: code, reason, retry });
}

function header_(r, name) {
  const h = r.getHeaders() || {};
  const k = Object.keys(h).find((x) => x.toLowerCase() === name.toLowerCase());
  return k ? h[k] : null;
}

// ---------- Drive ----------

const DRIVE = 'https://www.googleapis.com/drive/v3/files';

function driveMeta_(id) {
  return googleJson_('get', `${DRIVE}/${encodeURIComponent(id)}?fields=name,size,mimeType&supportsAllDrives=true`);
}

/** Bytes start..end (inclusive) of a Drive file, so files larger than 50 MB can be read in parts. */
function driveRange_(id, start, end) {
  const r = google_('get', `${DRIVE}/${encodeURIComponent(id)}?alt=media&supportsAllDrives=true`, { headers: { Range: `bytes=${start}-${end}` } });
  if (r.getResponseCode() !== 206 && r.getResponseCode() !== 200) throw upstreamError_(r);
  return r.getContent();
}

function driveBytes_(id) {
  const r = google_('get', `${DRIVE}/${encodeURIComponent(id)}?alt=media&supportsAllDrives=true`);
  if (r.getResponseCode() !== 200) throw upstreamError_(r);
  return r.getContent();
}

// ---- src/youtube.js ----
/**
 * YouTube adapter. Uploads a video from Drive with a resumable upload (any size, in chunks, across
 * several worker runs if needed), or edits a video already on YouTube, then sets the thumbnail,
 * captions and playlists. Every step records what it finished, so a retry never repeats work.
 */

const YT = 'https://www.googleapis.com/youtube/v3';
const YT_UPLOAD = 'https://www.googleapis.com/upload/youtube/v3';
const YT_PRIVACY = ['private', 'unlisted', 'public'];

const YouTube = {
  name: 'youtube',
  /** YouTube Data API: title in characters, description in UTF-8 bytes (Telugu takes 3 a letter), tags in total. */
  limits: { title: 100, descriptionBytes: 5000, tagsTotal: 500 },

  /** Checks a publish request and returns the clean version that is stored on the job. */
  validate(p, now) {
    const video = optFile_(p.video, 'video');
    const videoId = optText_(p.videoId, 'videoId', 20);
    if (!video && !videoId) throw new ApiError('invalid', 'Send video: {"driveFileId": ...} to upload, or videoId to edit a video already on YouTube');
    if (video && videoId) throw new ApiError('invalid', 'Send video or videoId, not both');

    const title = optText_(p.title, 'title', YouTube.limits.title);
    if (video && !title) throw new ApiError('invalid', 'title is required for an upload');
    if (title && /[<>]/.test(title)) throw new ApiError('invalid', 'title cannot contain < or >');
    const description = optText_(p.description, 'description', YouTube.limits.descriptionBytes);
    const bytes = utf8Bytes_(description || '');
    if (bytes > YouTube.limits.descriptionBytes) {
      throw new ApiError('invalid', `description is ${bytes} bytes; the limit is ${YouTube.limits.descriptionBytes} bytes (Telugu and other Indic letters take 3 bytes each, emoji 4)`);
    }
    if (description && /[<>]/.test(description)) throw new ApiError('invalid', 'description cannot contain < or >');

    let tags = null;
    if (p.tags !== undefined && p.tags !== null) {
      if (!Array.isArray(p.tags) || p.tags.some((t) => typeof t !== 'string')) throw new ApiError('invalid', 'tags must be a list of text');
      tags = p.tags.map((t) => t.trim()).filter(Boolean);
      // YouTube counts a tag with a space as if it had quotes around it, plus a comma between tags.
      const len = tags.reduce((n, t) => n + t.length + (t.includes(' ') ? 2 : 0), 0) + Math.max(tags.length - 1, 0);
      if (len > YouTube.limits.tagsTotal) throw new ApiError('invalid', `tags add up to ${len} characters; the limit is ${YouTube.limits.tagsTotal}`);
    }

    const categoryId = p.categoryId === undefined || p.categoryId === null ? null : String(p.categoryId);
    if (categoryId && !/^\d+$/.test(categoryId)) throw new ApiError('invalid', 'categoryId must be a number like 28');

    const publishAt = optFutureTime_(p.publishAt, 'publishAt', now);
    let privacy = optText_(p.privacy, 'privacy', 10);
    if (privacy && !YT_PRIVACY.includes(privacy)) throw new ApiError('invalid', `privacy must be one of ${YT_PRIVACY.join(', ')}`);
    if (publishAt && privacy && privacy !== 'private') {
      throw new ApiError('invalid', 'A scheduled video must be private until publishAt; leave privacy out or send "private"');
    }
    if (publishAt) privacy = 'private';
    if (video && !privacy) privacy = 'private';

    let captions = [];
    if (p.captions !== undefined && p.captions !== null) {
      if (!Array.isArray(p.captions)) throw new ApiError('invalid', 'captions must be a list');
      captions = p.captions.map((c, i) => {
        const f = optFile_(c, `captions[${i}]`);
        const language = optText_(c.language, `captions[${i}].language`, 20);
        if (!language) throw new ApiError('invalid', `captions[${i}].language is required, like "en"`);
        return { driveFileId: f.driveFileId, language, name: optText_(c.name, `captions[${i}].name`, 150) || '' };
      });
    }

    let playlists = [];
    if (p.playlists !== undefined && p.playlists !== null) {
      if (!Array.isArray(p.playlists) || p.playlists.some((x) => typeof x !== 'string' || !x)) throw new ApiError('invalid', 'playlists must be a list of playlist ids or exact playlist titles');
      playlists = p.playlists;
    }

    return {
      video, videoId, title, description, tags, categoryId: categoryId || (video ? '22' : null),
      language: optText_(p.language, 'language', 20),
      madeForKids: video ? optBool_(p.madeForKids, 'madeForKids') === true : optBool_(p.madeForKids, 'madeForKids'),
      aiGenerated: optBool_(p.aiGenerated, 'aiGenerated'),
      privacy, publishAt,
      thumbnail: optFile_(p.thumbnail, 'thumbnail'),
      captions, playlists,
    };
  },

  steps(post) {
    return [post.video ? 'upload' : 'edit', 'thumbnail', 'captions', 'playlists', 'check'];
  },

  run(step, job, ctx) {
    return YT_STEPS[step](job.post, job.state, ctx);
  },

  /** The channel the service posts to. */
  whoami() {
    const r = googleJson_('get', `${YT}/channels?part=snippet&mine=true`);
    const c = (r.items || [])[0];
    if (!c) throw new ApiError('not_found', 'This Google account has no YouTube channel');
    return { id: c.id, title: c.snippet.title, url: `https://www.youtube.com/channel/${c.id}` };
  },

  /** Subscribers, total channel views and the newest uploads with views, likes and comments. YouTube has no reach, so that is null. */
  stats(limit) {
    const c = (googleJson_('get', `${YT}/channels?part=statistics,contentDetails&mine=true`).items || [])[0];
    if (!c) throw new ApiError('not_found', 'This Google account has no YouTube channel');
    const st = c.statistics || {};
    const num = (v) => (v == null ? null : Number(v));
    const ids = (googleJson_('get', `${YT}/playlistItems?part=contentDetails&playlistId=${c.contentDetails.relatedPlaylists.uploads}&maxResults=${Math.min(limit, 50)}`).items || [])
      .map((i) => i.contentDetails.videoId);
    const videos = ids.length ? googleJson_('get', `${YT}/videos?part=snippet,statistics&id=${ids.join(',')}`).items || [] : [];
    return {
      followers: st.hiddenSubscriberCount ? null : num(st.subscriberCount),
      channelViews: num(st.viewCount),
      posts: videos.map((v) => ({
        url: `https://youtu.be/${v.id}`, title: v.snippet.title, at: v.snippet.publishedAt,
        likes: num(v.statistics && v.statistics.likeCount), comments: num(v.statistics && v.statistics.commentCount),
        views: num(v.statistics && v.statistics.viewCount), reach: null,
      })),
    };
  },

  /** Newest top-level comments on the channel's videos, minus the channel's own, with whether the channel replied. */
  comments(limit) {
    const me = YouTube.whoami().id;
    const r = googleJson_('get', `${YT}/commentThreads?part=snippet,replies&allThreadsRelatedToChannelId=${me}&order=time&maxResults=${limit}&textFormat=plainText`);
    const items = (r.items || []).filter((t) => ytAuthor_(t.snippet.topLevelComment) !== me);
    const ids = [...new Set(items.map((t) => t.snippet.videoId))];
    const titles = {};
    if (ids.length) (googleJson_('get', `${YT}/videos?part=snippet&id=${ids.join(',')}`).items || []).forEach((v) => { titles[v.id] = v.snippet.title; });
    return {
      comments: items.map((t) => {
        const c = t.snippet.topLevelComment.snippet;
        return {
          id: t.id, author: c.authorDisplayName, text: c.textDisplay, at: c.publishedAt, likes: c.likeCount,
          videoId: t.snippet.videoId, videoTitle: titles[t.snippet.videoId] || '',
          url: `https://www.youtube.com/watch?v=${t.snippet.videoId}&lc=${t.id}`,
          replies: t.snippet.totalReplyCount,
          replied: ((t.replies && t.replies.comments) || []).some((x) => ytAuthor_(x) === me),
        };
      }),
    };
  },

  /** Replies to a top-level comment. Sending the same text again returns the first reply instead of posting twice. */
  reply(commentId, text) {
    const me = YouTube.whoami().id;
    const mine = (googleJson_('get', `${YT}/comments?part=snippet&parentId=${encodeURIComponent(commentId)}&maxResults=100&textFormat=plainText`).items || [])
      .find((x) => ytAuthor_(x) === me && x.snippet.textOriginal === text);
    const c = mine || googleJson_('post', `${YT}/comments?part=snippet`, { json: { snippet: { parentId: commentId, textOriginal: text } } });
    return { reply: { id: c.id, commentId, text: c.snippet.textOriginal, existing: !!mine } };
  },
};

function ytAuthor_(c) {
  return c && c.snippet && c.snippet.authorChannelId && c.snippet.authorChannelId.value;
}

function ytSnippet_(p, base) {
  const s = {};
  ['title', 'description', 'tags', 'categoryId', 'defaultLanguage', 'defaultAudioLanguage'].forEach((k) => {
    if (base && base[k] !== undefined) s[k] = base[k];
  });
  if (p.title) s.title = p.title;
  if (p.description !== null) s.description = p.description;
  if (p.tags) s.tags = p.tags;
  if (p.categoryId) s.categoryId = p.categoryId;
  if (p.language) { s.defaultLanguage = p.language; s.defaultAudioLanguage = p.language; }
  return s;
}

function ytStatus_(p, base) {
  const s = {};
  ['privacyStatus', 'publishAt', 'embeddable', 'license', 'publicStatsViewable', 'selfDeclaredMadeForKids', 'containsSyntheticMedia'].forEach((k) => {
    if (base && base[k] !== undefined) s[k] = base[k];
  });
  if (p.privacy) s.privacyStatus = p.privacy;
  if (p.publishAt) s.publishAt = p.publishAt;
  else if (p.privacy && p.privacy !== 'private') delete s.publishAt;
  if (p.madeForKids !== null) s.selfDeclaredMadeForKids = p.madeForKids;
  if (p.aiGenerated !== null) s.containsSyntheticMedia = p.aiGenerated;
  return s;
}

const YT_STEPS = {
  upload(p, s, ctx) {
    if (s.videoId) return 'next';
    if (!s.size) {
      const m = driveMeta_(p.video.driveFileId);
      s.size = Number(m.size);
      s.mime = m.mimeType || 'video/mp4';
      if (!s.size) throw new ApiError('invalid', 'The video file in Drive is empty');
    }
    if (!s.session) {
      const r = google_('post', `${YT_UPLOAD}/videos?uploadType=resumable&part=snippet,status`, {
        json: { snippet: ytSnippet_(p), status: ytStatus_(p) },
        headers: { 'X-Upload-Content-Length': String(s.size), 'X-Upload-Content-Type': s.mime },
      });
      if (r.getResponseCode() !== 200) throw upstreamError_(r);
      s.session = header_(r, 'Location');
      s.offset = 0;
      ctx.save();
    }
    while (s.offset < s.size) {
      if (ctx.outOfTime()) return 'pause';
      const end = Math.min(s.offset + CHUNK_BYTES, s.size) - 1;
      const r = google_('put', s.session, {
        payload: driveRange_(p.video.driveFileId, s.offset, end),
        contentType: s.mime,
        headers: { 'Content-Range': `bytes ${s.offset}-${end}/${s.size}` },
      });
      const code = r.getResponseCode();
      if (code === 200 || code === 201) {
        s.videoId = JSON.parse(r.getContentText()).id;
        s.offset = s.size;
        ctx.save();
        break;
      }
      if (code === 308) {
        const range = header_(r, 'Range'); // "bytes=0-12345": what YouTube has so far
        s.offset = range ? Number(String(range).split('-')[1]) + 1 : 0;
        ctx.save();
        continue;
      }
      if (code === 404 || code === 410) {
        // The upload session expired (they last about a week); start the upload again.
        delete s.session;
        s.offset = 0;
        ctx.save();
        throw new ApiError('upstream', 'The upload session expired; starting the upload again', { retry: 'transient' });
      }
      throw upstreamError_(r);
    }
    return 'next';
  },

  edit(p, s) {
    if (s.videoId) return 'next';
    const r = googleJson_('get', `${YT}/videos?part=snippet,status&id=${encodeURIComponent(p.videoId)}`);
    const v = (r.items || [])[0];
    if (!v) throw new ApiError('not_found', `No video ${p.videoId} on this channel`);
    googleJson_('put', `${YT}/videos?part=snippet,status`, {
      json: { id: p.videoId, snippet: ytSnippet_(p, v.snippet), status: ytStatus_(p, v.status) },
    });
    s.videoId = p.videoId;
    return 'next';
  },

  thumbnail(p, s, ctx) {
    if (!p.thumbnail || s.thumbnailDone) return 'next';
    ctx.optional('thumbnail', () => {
      const m = driveMeta_(p.thumbnail.driveFileId);
      if (Number(m.size) > 2 * 1024 * 1024) throw new ApiError('invalid', 'The thumbnail is over YouTube\'s 2 MB limit');
      const r = google_('post', `${YT_UPLOAD}/thumbnails/set?videoId=${encodeURIComponent(s.videoId)}&uploadType=media`, {
        payload: driveBytes_(p.thumbnail.driveFileId), contentType: m.mimeType || 'image/jpeg',
      });
      if (r.getResponseCode() !== 200) throw upstreamError_(r);
    });
    s.thumbnailDone = true;
    return 'next';
  },

  captions(p, s, ctx) {
    s.captionsDone = s.captionsDone || [];
    p.captions.forEach((c, i) => {
      if (s.captionsDone.includes(i)) return;
      ctx.optional(`captions ${c.language}`, () => {
        const boundary = `pub${Date.now()}`;
        const head = `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify({ snippet: { videoId: s.videoId, language: c.language, name: c.name, isDraft: false } })}\r\n--${boundary}\r\nContent-Type: application/octet-stream\r\n\r\n`;
        const body = Utilities.newBlob(head).getBytes()
          .concat(driveBytes_(c.driveFileId))
          .concat(Utilities.newBlob(`\r\n--${boundary}--`).getBytes());
        const r = google_('post', `${YT_UPLOAD}/captions?part=snippet&uploadType=multipart`, { payload: body, contentType: `multipart/related; boundary=${boundary}` });
        if (r.getResponseCode() !== 200) throw upstreamError_(r);
      });
      s.captionsDone.push(i);
      ctx.save();
    });
    return 'next';
  },

  playlists(p, s, ctx) {
    s.playlistsDone = s.playlistsDone || [];
    const todo = p.playlists.filter((x) => !s.playlistsDone.includes(x));
    if (!todo.length) return 'next';
    let mine = null;
    todo.forEach((want) => {
      ctx.optional(`playlist ${want}`, () => {
        if (!mine) mine = ytMyPlaylists_();
        let hit = mine.find((pl) => pl.id === want) || mine.find((pl) => pl.title === want);
        if (!hit && /^PL[\w-]{10,}$/.test(want)) throw new ApiError('not_found', `No playlist with id "${want}" on this channel`);
        if (!hit) { // a title the channel doesn't have yet: make it as a public playlist
          const made = googleJson_('post', `${YT}/playlists?part=snippet,status`, {
            json: { snippet: { title: want }, status: { privacyStatus: 'public' } },
          });
          hit = { id: made.id, title: want };
          mine.push(hit);
        }
        googleJson_('post', `${YT}/playlistItems?part=snippet`, {
          json: { snippet: { playlistId: hit.id, resourceId: { kind: 'youtube#video', videoId: s.videoId } } },
        });
      });
      s.playlistsDone.push(want);
      ctx.save();
    });
    return 'next';
  },

  /** Reads the video back, so the result shows what YouTube actually did. */
  check(p, s, ctx) {
    const r = googleJson_('get', `${YT}/videos?part=status,snippet&id=${encodeURIComponent(s.videoId)}`);
    const v = (r.items || [])[0];
    if (!v) throw new ApiError('upstream', `YouTube does not list video ${s.videoId}`, { retry: 'transient' });
    const st = v.status || {};
    if (p.privacy && st.privacyStatus !== p.privacy) {
      ctx.warn(`Asked for ${p.privacy} but YouTube set ${st.privacyStatus}. Check the channel in YouTube Studio (see the FAQ).`);
    }
    if (p.publishAt && !st.publishAt) ctx.warn('Asked for a scheduled time but YouTube did not keep it. Check the video in YouTube Studio.');
    ctx.result({
      videoId: s.videoId,
      url: `https://youtu.be/${s.videoId}`,
      studioUrl: `https://studio.youtube.com/video/${s.videoId}/edit`,
      title: v.snippet && v.snippet.title,
      privacy: st.privacyStatus,
      publishAt: st.publishAt || null,
      uploadStatus: st.uploadStatus || null,
    });
    return 'next';
  },
};

function ytMyPlaylists_() {
  const out = [];
  let page = '';
  do {
    const r = googleJson_('get', `${YT}/playlists?part=snippet&mine=true&maxResults=50${page ? `&pageToken=${page}` : ''}`);
    (r.items || []).forEach((pl) => out.push({ id: pl.id, title: pl.snippet.title }));
    page = r.nextPageToken || '';
  } while (page);
  return out;
}

// ---- src/youtube-auth.js ----
/**
 * YouTube sign-in. The script's own Google sign-in can only post as the account's personal channel,
 * so a brand channel needs its own OAuth sign-in, where Google asks which channel to use.
 *
 * Needs two Script Properties from a Google Cloud OAuth client (type "Web application", redirect URI
 * https://script.google.com/macros/d/<script id>/usercallback): YT_CLIENT_ID and YT_CLIENT_SECRET.
 * Then run connectYouTube() in the editor and open the link it logs. Without them, the script's own
 * sign-in is used.
 *
 * More than one channel: each extra channel is an "account" with a short name ("second"). Its sign-in is
 * kept beside the main one, and a call that sends "account" uses it. The main channel needs no name.
 */

/** The account the current API call or job works as; '' is the main channel. */
let ACCOUNT = '';

function accountName_(v) {
  if (v === undefined || v === null || v === '') return '';
  if (typeof v !== 'string' || !/^[a-z0-9-]{1,30}$/.test(v)) throw new ApiError('invalid', 'account must be a short name of small letters, digits or dashes, like "second"');
  return v;
}

function accountKey_(k, account) {
  const a = account === undefined ? ACCOUNT : account;
  return a ? `${k}_${a.toUpperCase().replace(/-/g, '_')}` : k;
}

function ytAccountConnected_(account) {
  return !account || !!props_().getProperty(accountKey_('YT_REFRESH_TOKEN', account));
}

const YT_SCOPES = ['https://www.googleapis.com/auth/youtube.upload', 'https://www.googleapis.com/auth/youtube.force-ssl'];

/** Logs the sign-in link. Open it, pick the channel, press Allow. With a name, it connects that extra account. */
function connectYouTube(account) {
  const name = accountName_(typeof account === 'string' ? account : '');
  const p = props_();
  if (!p.getProperty('YT_CLIENT_ID') || !p.getProperty('YT_CLIENT_SECRET')) {
    throw new Error('Add the YT_CLIENT_ID and YT_CLIENT_SECRET script properties first (see the FAQ).');
  }
  const state = ScriptApp.newStateToken().withMethod('youTubeCallback').withArgument('account', name).withTimeout(600).createToken();
  const q = {
    client_id: p.getProperty('YT_CLIENT_ID'), redirect_uri: ytRedirectUri_(), response_type: 'code',
    scope: YT_SCOPES.join(' '), access_type: 'offline', prompt: 'consent select_account', state,
  };
  const url = `https://accounts.google.com/o/oauth2/v2/auth?${Object.keys(q).map((k) => `${k}=${encodeURIComponent(q[k])}`).join('&')}`;
  console.log(`Open this link, pick the channel, and press Allow (valid 10 minutes):\n${url}`);
  return url;
}

/**
 * The same from the editor, which can't pass a name: put the account name in the Script Property
 * YT_CONNECT_ACCOUNT, run this, and open the link it logs.
 */
function connectYouTubeAccount() {
  const name = props_().getProperty('YT_CONNECT_ACCOUNT');
  if (!name) throw new Error('Add the script property YT_CONNECT_ACCOUNT with the account name first, like "second".');
  return connectYouTube(name);
}

function youTubeCallback(req) {
  const p = props_();
  const r = UrlFetchApp.fetch('https://oauth2.googleapis.com/token', {
    method: 'post', muteHttpExceptions: true,
    payload: {
      code: req.parameter.code, client_id: p.getProperty('YT_CLIENT_ID'), client_secret: p.getProperty('YT_CLIENT_SECRET'),
      redirect_uri: ytRedirectUri_(), grant_type: 'authorization_code',
    },
  });
  const t = JSON.parse(r.getContentText());
  if (!t.refresh_token) return HtmlService.createHtmlOutput(`Sign-in failed: ${String(t.error_description || t.error || r.getResponseCode())}`);
  ACCOUNT = accountName_((req.parameter && req.parameter.account) || '');
  p.setProperty(accountKey_('YT_REFRESH_TOKEN'), t.refresh_token);
  CacheService.getScriptCache().put(accountKey_('YT_ACCESS'), t.access_token, 3000);
  let who = '';
  try { who = YouTube.whoami().title; } catch (err) { who = `(could not read the channel: ${err.message})`; }
  return HtmlService.createHtmlOutput(`Connected${ACCOUNT ? ` as the account "${ACCOUNT}"` : ''}. Social Media Publisher now posts to the YouTube channel: ${who}. You can close this tab.`);
}

function ytRedirectUri_() {
  return `https://script.google.com/macros/d/${ScriptApp.getScriptId()}/usercallback`;
}

/** Access token for YouTube calls: the channel sign-in if there is one, else the script's own. */
function youTubeToken_() {
  const p = props_();
  const refresh = p.getProperty(accountKey_('YT_REFRESH_TOKEN'));
  if (!refresh && ACCOUNT) throw new ApiError('not_connected', `The YouTube account "${ACCOUNT}" is not connected; call connectYouTube with that account first`, { retry: false });
  if (!refresh) return ScriptApp.getOAuthToken();
  const cache = CacheService.getScriptCache();
  const hit = cache.get(accountKey_('YT_ACCESS'));
  if (hit) return hit;
  const r = UrlFetchApp.fetch('https://oauth2.googleapis.com/token', {
    method: 'post', muteHttpExceptions: true,
    payload: { client_id: p.getProperty('YT_CLIENT_ID'), client_secret: p.getProperty('YT_CLIENT_SECRET'), refresh_token: refresh, grant_type: 'refresh_token' },
  });
  const t = JSON.parse(r.getContentText());
  if (!t.access_token) throw new ApiError('upstream', `YouTube sign-in failed (${t.error || r.getResponseCode()}); run connectYouTube() again`, { status: r.getResponseCode(), retry: false });
  cache.put(accountKey_('YT_ACCESS'), t.access_token, Math.min(Number(t.expires_in || 3600) - 300, 3000));
  return t.access_token;
}

// ---- src/meta.js ----
/**
 * Meta sign-in and Graph API helpers, shared by the Instagram and Facebook adapters.
 *
 * Needs two Script Properties from a Meta developer app: META_APP_ID and META_APP_SECRET, with
 * https://script.google.com/macros/d/<script id>/usercallback in the app's "Valid OAuth Redirect URIs".
 * Then run connectMeta() in the editor and open the link it logs. The callback keeps a Page token that
 * does not expire, the Page id and the id of the Instagram professional account linked to that Page.
 *
 * More than one Page: each extra Page (with its Instagram account) is an "account" with a short name, the
 * same as extra YouTube channels. Its Page token, Page id and Instagram id are kept beside the main ones
 * (META_PAGE_ID_<NAME> and so on), and a call that sends "account" uses them.
 */

const GRAPH_VERSION = 'v24.0';
const GRAPH = `https://graph.facebook.com/${GRAPH_VERSION}`;
const META_SCOPES = [
  'pages_show_list', 'pages_read_engagement', 'pages_manage_posts', 'business_management',
  'instagram_basic', 'instagram_content_publish',
  // Views and reach of posts, for the stats action. Accounts connected before these were added get null views until connectMeta() is run again.
  'instagram_manage_insights', 'read_insights',
  // Reading and answering comments, for the comments and reply actions. Also needs connectMeta() run again.
  'instagram_manage_comments', 'pages_read_user_content', 'pages_manage_engagement',
];

/**
 * Logs the sign-in link. Open it, pick the Page and its Instagram account, press Continue.
 * With a name, it connects that extra account; match (a Page name or id, or an Instagram @username) picks
 * the Page when the sign-in shares more than one.
 */
function connectMeta(account, match) {
  const name = accountName_(typeof account === 'string' ? account : '');
  const p = props_();
  if (!p.getProperty('META_APP_ID') || !p.getProperty('META_APP_SECRET')) {
    throw new Error('Add the META_APP_ID and META_APP_SECRET script properties first (see the FAQ).');
  }
  const state = ScriptApp.newStateToken().withMethod('metaCallback').withArgument('account', name)
    .withArgument('match', typeof match === 'string' ? match : '').withTimeout(600).createToken();
  const q = { client_id: p.getProperty('META_APP_ID'), redirect_uri: ytRedirectUri_(), response_type: 'code', state };
  // Apps that use Facebook Login for Business name a configuration instead of a list of permissions.
  if (p.getProperty('META_CONFIG_ID')) q.config_id = p.getProperty('META_CONFIG_ID'); else q.scope = META_SCOPES.join(',');
  const url = `https://www.facebook.com/${GRAPH_VERSION}/dialog/oauth?${Object.keys(q).map((k) => `${k}=${encodeURIComponent(q[k])}`).join('&')}`;
  console.log(`Open this link, pick the Page${name ? ` for the account "${name}"` : ''} and its Instagram account, and press Continue (valid 10 minutes):\n${url}`);
  return url;
}

/**
 * The Page the sign-in shared that this account should use: match first, then the one it had. With nothing
 * stored yet, the main account takes the first Page and an extra one takes the only Page; otherwise null.
 */
function pickMetaPage_(pages, account, match, current) {
  const m = String(match || '').replace(/^@/, '').toLowerCase();
  if (m) return pages.find((x) => x.id === m || String(x.name || '').toLowerCase() === m
    || (x.instagram_business_account && String(x.instagram_business_account.username || '').toLowerCase() === m)) || null;
  const had = pages.find((x) => x.id === current);
  if (had) return had;
  if (current) return null; // its Page wasn't shared: never switch to another one silently
  if (account && pages.length > 1) return null; // an extra account never guesses between Pages
  return pages[0];
}

function metaCallback(req) {
  try {
    const p = props_();
    const prm = req.parameter || {};
    ACCOUNT = accountName_(prm.account || '');
    const app = { client_id: p.getProperty('META_APP_ID'), client_secret: p.getProperty('META_APP_SECRET') };
    const short = metaGet_('/oauth/access_token', Object.assign({ redirect_uri: ytRedirectUri_(), code: prm.code }, app));
    // A Page token read with a long-lived user token never expires.
    const long = metaGet_('/oauth/access_token', Object.assign({ grant_type: 'fb_exchange_token', fb_exchange_token: short.access_token }, app));
    const pages = metaGet_('/me/accounts', { fields: 'id,name,access_token,instagram_business_account{id,username}', access_token: long.access_token }).data || [];
    if (!pages.length) return HtmlService.createHtmlOutput('Sign-in worked, but no Facebook Page was shared. Run connectMeta() again and tick your Page.');
    const page = pickMetaPage_(pages, ACCOUNT, prm.match, p.getProperty(accountKey_('META_PAGE_ID')));
    if (!page) {
      const names = pages.map((x) => x.name + (x.instagram_business_account ? ` (@${x.instagram_business_account.username})` : '')).join(', ');
      return HtmlService.createHtmlOutput(`Sign-in worked, but it isn't clear which Page is ${ACCOUNT ? `the account "${ACCOUNT}"` : 'meant'}. Shared: ${names}. Run connectMeta again with match set to one of them.`);
    }
    p.setProperties({ [accountKey_('META_PAGE_ID')]: page.id, [accountKey_('META_PAGE_TOKEN')]: page.access_token });
    const ig = page.instagram_business_account;
    if (ig) p.setProperty(accountKey_('META_IG_ID'), ig.id); else p.deleteProperty(accountKey_('META_IG_ID'));
    const igText = ig ? `Instagram: @${ig.username}.` : 'No Instagram professional account is linked to this Page, so Instagram posts will fail until one is.';
    const mainId = p.getProperty('META_PAGE_ID');
    const mainText = ACCOUNT && mainId && !pages.some((x) => x.id === mainId)
      ? ' Warning: the main Page was not ticked, so Meta may stop its posts. Run connectMeta again and tick every Page.' : '';
    return HtmlService.createHtmlOutput(`Connected${ACCOUNT ? ` as the account "${ACCOUNT}"` : ''}. Facebook Page: ${page.name}. ${igText}${mainText} You can close this tab.`);
  } catch (err) {
    return HtmlService.createHtmlOutput(`Sign-in failed: ${err.message}`);
  }
}

function metaConnected_(account) {
  return !account || !!props_().getProperty(accountKey_('META_PAGE_TOKEN', account));
}

function metaConfig_(needIg) {
  const p = props_();
  const c = { token: p.getProperty(accountKey_('META_PAGE_TOKEN')), pageId: p.getProperty(accountKey_('META_PAGE_ID')), igId: p.getProperty(accountKey_('META_IG_ID')) };
  if (!c.token || !c.pageId) {
    throw new ApiError('not_connected', ACCOUNT ? `The Meta account "${ACCOUNT}" is not connected; call connectMeta with that account first`
      : 'Meta is not connected yet; run connectMeta() (see the FAQ)', ACCOUNT ? { retry: false } : undefined);
  }
  if (needIg && !c.igId) throw new ApiError('not_connected', 'No Instagram professional account is linked to the Facebook Page; link one, then run connectMeta() again');
  return c;
}

function metaQuery_(params) {
  return Object.keys(params).filter((k) => params[k] !== null && params[k] !== undefined)
    .map((k) => `${k}=${encodeURIComponent(params[k])}`).join('&');
}

function metaFetch_(method, path, params) {
  const url = path.startsWith('https://') ? path : `${GRAPH}${path}`;
  const r = method === 'get'
    ? UrlFetchApp.fetch(`${url}?${metaQuery_(params)}`, { method: 'get', muteHttpExceptions: true })
    : UrlFetchApp.fetch(url, { method: 'post', muteHttpExceptions: true, payload: metaQuery_(params), contentType: 'application/x-www-form-urlencoded' });
  const code = r.getResponseCode();
  if (code >= 200 && code < 300) return JSON.parse(r.getContentText() || '{}');
  throw metaError_(r);
}

function metaGet_(path, params) { return metaFetch_('get', path, params); }
function metaPost_(path, params) { return metaFetch_('post', path, params); }

/** Sends bytes to Meta's upload host (rupload.facebook.com), resuming at `offset`. */
function metaUpload_(url, token, bytes, offset, size) {
  const r = UrlFetchApp.fetch(url, {
    method: 'post', muteHttpExceptions: true, payload: bytes, contentType: 'application/octet-stream',
    headers: { Authorization: `OAuth ${token}`, offset: String(offset), file_size: String(size) },
  });
  if (r.getResponseCode() !== 200) throw metaError_(r, true);
  return JSON.parse(r.getContentText() || '{}');
}

/** raw: keep the whole answer in the message (the upload host's short messages hide the useful fields). */
function metaError_(r, raw) {
  const code = r.getResponseCode();
  const text = String(r.getContentText() || '');
  let e = {};
  // The Graph API puts errors under "error"; the upload host (rupload) uses "debug_info".
  try { const b = JSON.parse(text); e = b.error || b.debug_info || {}; } catch (err) { e = {}; }
  const reason = e.error_user_msg || e.message || '';
  const message = raw || !reason ? text.slice(0, 500) : reason;
  let retry = false;
  // 4, 17, 32, 613: rate limits. 2 and is_transient: Meta's own temporary errors. An error with no
  // reason at all (seen right after an Instagram container is made) has passed on the next try.
  if ([4, 17, 32, 613].includes(e.code)) retry = 'quota';
  else if (code >= 500 || e.is_transient || e.retriable || e.code === 2 || (!reason && !e.code)) retry = 'transient';
  return new ApiError('upstream', `Meta answered ${code}${e.code ? ` (code ${e.code}${e.error_subcode ? `/${e.error_subcode}` : ''})` : ''}: ${message}`, { status: code, reason: e.code || null, subcode: e.error_subcode || null, retry });
}

/** Uploads a Drive file to a rupload URL in CHUNK_BYTES parts, recording progress in s.offset. */
function metaSendFile_(p, s, ctx, url, token) {
  while (s.offset < s.size) {
    if (ctx.outOfTime()) return 'pause';
    const end = Math.min(s.offset + CHUNK_BYTES, s.size) - 1;
    metaUpload_(url, token, driveRange_(p.video.driveFileId, s.offset, end), s.offset, s.size);
    s.offset = end + 1;
    ctx.save();
  }
  return 'next';
}

function metaFileSize_(p, s) {
  if (s.size) return;
  const m = driveMeta_(p.video.driveFileId);
  s.size = Number(m.size);
  if (!s.size) throw new ApiError('invalid', 'The video file in Drive is empty');
  s.offset = 0;
}

/**
 * Calls fn for each post until one fails, then gives null for the rest: a missing insights permission
 * fails every call the same way, so one failure is enough to stop asking.
 */
function metaInsightsEach_(posts, fn) {
  let ok = true;
  return posts.map((p) => {
    if (!ok) return null;
    try { return fn(p); } catch (e) { ok = false; console.log(`Meta insights: ${e.message}`); return null; }
  });
}

/** The value of one metric in an insights answer, or null. */
function metaMetric_(r, name) {
  const m = (r.data || []).find((x) => x.name === name);
  const v = m && m.values && m.values[0] ? m.values[0].value : m && m.total_value ? m.total_value.value : null;
  return v == null ? null : Number(v);
}

const firstLine_ = (s) => String(s || '').split('\n')[0].slice(0, 100);

// ---- src/instagram.js ----
/**
 * Instagram adapter: posts a video from Drive as a Reel on the Instagram professional account linked
 * to the connected Facebook Page (see src/meta.js). Instagram has no private or scheduled posts in its
 * API, so publishAt makes the job wait in the queue until then.
 */

const Instagram = {
  name: 'instagram',
  /** Caption in characters; hashtags cut from 30 to 5 per post in December 2025. */
  limits: { caption: 2200, hashtags: 5, title: 100 },

  validate(p, now) {
    const video = igVideo_(p.video);
    const caption = optText_(p.caption, 'caption', Instagram.limits.caption);
    const tags = (caption || '').match(/#[^\s#]+/g) || [];
    if (tags.length > Instagram.limits.hashtags) {
      throw new ApiError('invalid', `caption has ${tags.length} hashtags; Instagram allows at most ${Instagram.limits.hashtags} since December 2025`);
    }
    const coverMs = p.coverAtMs === undefined || p.coverAtMs === null ? null : Number(p.coverAtMs);
    if (coverMs !== null && !(coverMs >= 0)) throw new ApiError('invalid', 'coverAtMs must be a number of milliseconds into the video');
    const coverUrl = p.coverUrl === undefined || p.coverUrl === null ? null : p.coverUrl;
    if (coverUrl !== null && (typeof coverUrl !== 'string' || coverUrl.length > 2000 || !/^https:\/\/[^\s]+$/.test(coverUrl))) {
      throw new ApiError('invalid', 'coverUrl must be a public https link to a JPG');
    }
    const publishAt = optFutureTime_(p.publishAt, 'publishAt', now);
    return {
      video, caption, coverAtMs: coverMs, coverUrl, shareToFeed: optBool_(p.shareToFeed, 'shareToFeed') !== false,
      title: optText_(p.title, 'title', Instagram.limits.title) || (caption || '').split('\n')[0].slice(0, Instagram.limits.title),
      notBefore: publishAt,
    };
  },

  steps() {
    return ['container', 'upload', 'process', 'publish', 'check'];
  },

  run(step, job, ctx) {
    return IG_STEPS[step](job.post, job.state, ctx, metaConfig_(true));
  },

  /** Followers and the newest posts with likes, comments, views and reach (views need instagram_manage_insights). */
  stats(limit) {
    const c = metaConfig_(true);
    const me = metaGet_(`/${c.igId}`, { fields: 'followers_count', access_token: c.token });
    const media = metaGet_(`/${c.igId}/media`, { fields: 'id,permalink,caption,timestamp,like_count,comments_count', limit, access_token: c.token }).data || [];
    const ins = metaInsightsEach_(media, (m) => metaGet_(`/${m.id}/insights`, { metric: 'views,reach', access_token: c.token }));
    return {
      followers: me.followers_count == null ? null : me.followers_count,
      posts: media.map((m, i) => ({
        url: m.permalink, title: firstLine_(m.caption), at: m.timestamp, likes: m.like_count == null ? null : m.like_count,
        comments: m.comments_count == null ? null : m.comments_count, views: ins[i] && metaMetric_(ins[i], 'views'), reach: ins[i] && metaMetric_(ins[i], 'reach'),
      })),
    };
  },

  /** Newest comments on the newest Reels, minus the account's own, with whether the account replied (needs instagram_manage_comments). */
  comments(limit) {
    const c = metaConfig_(true);
    const me = metaGet_(`/${c.igId}`, { fields: 'username', access_token: c.token }).username;
    const media = (metaGet_(`/${c.igId}/media`, { fields: 'id,permalink,caption,comments_count', limit: 25, access_token: c.token }).data || [])
      .filter((m) => m.comments_count);
    const out = [];
    media.forEach((m) => {
      const list = metaGet_(`/${m.id}/comments`, { fields: 'id,text,username,timestamp,like_count,replies{username,text}', limit: 50, access_token: c.token }).data || [];
      list.filter((x) => x.username !== me).forEach((x) => {
        const replies = (x.replies && x.replies.data) || [];
        out.push({
          id: x.id, author: x.username, text: x.text, at: x.timestamp, likes: x.like_count == null ? 0 : x.like_count,
          videoId: m.id, videoTitle: firstLine_(m.caption), url: m.permalink, replies: replies.length,
          replied: replies.some((r) => r.username === me),
        });
      });
    });
    out.sort((a, b) => String(b.at).localeCompare(String(a.at)));
    return { comments: out.slice(0, limit) };
  },

  /** Replies to a comment. Sending the same text again returns the first reply instead of posting twice. */
  reply(commentId, text) {
    const c = metaConfig_(true);
    const me = metaGet_(`/${c.igId}`, { fields: 'username', access_token: c.token }).username;
    const id = encodeURIComponent(commentId);
    const mine = (metaGet_(`/${id}/replies`, { fields: 'id,text,username', limit: 100, access_token: c.token }).data || [])
      .find((x) => x.username === me && x.text === text);
    const r = mine || metaPost_(`/${id}/replies`, { message: text, access_token: c.token });
    return { reply: { id: r.id, commentId, text, existing: !!mine } };
  },

  whoami() {
    const c = metaConfig_(true);
    const r = metaGet_(`/${c.igId}`, { fields: 'username,name', access_token: c.token });
    return { id: c.igId, title: r.username, url: `https://www.instagram.com/${r.username}/` };
  },
};

/**
 * The video: {"driveFileId": ...}, {"url": "https://..."} or both. With a url, Instagram fetches the video
 * itself, which is the dependable way; the Drive file is then only the fallback.
 */
function igVideo_(v) {
  if (!v || typeof v !== 'object' || v.url === undefined || v.url === null) {
    const file = optFile_(v, 'video');
    if (!file) throw new ApiError('invalid', 'Send video: {"driveFileId": ...} or {"url": "https://..."}');
    return file;
  }
  if (typeof v.url !== 'string' || v.url.length > 2000 || !/^https:\/\/[^\s]+$/.test(v.url)) {
    throw new ApiError('invalid', 'video.url must be a public https link to the video file');
  }
  const out = { url: v.url };
  if (v.driveFileId !== undefined && v.driveFileId !== null) out.driveFileId = optFile_({ driveFileId: v.driveFileId }, 'video').driveFileId;
  return out;
}

// How long the process step waits for Instagram before it starts again with a new container.
let IG_DOUBT_MS = 10 * 60 * 1000; // after the upload host refused the upload
let IG_PROCESS_MS = 20 * 60 * 1000; // after a clean upload or a link
// How long one worker run keeps checking before it lets other jobs go first.
let IG_POLL_MS = 40 * 1000;

/** Forgets the container, so the job's next try starts again from the container step. */
function igStartOver_(s, ctx) {
  ['containerId', 'uploadUrl', 'byUrl', 'uploadDoubt', 'processSince', 'size'].forEach((k) => { delete s[k]; });
  s.offset = 0;
  s.stepIndex = 0;
  ctx.save();
}

const IG_STEPS = {
  /** With a video link Instagram fetches the file itself; without one the upload step sends it from Drive. */
  container(p, s, ctx, c) {
    if (s.containerId) return 'next';
    const byUrl = !!p.video.url && !s.urlFailed;
    const r = metaPost_(`/${c.igId}/media`, Object.assign({
      media_type: 'REELS', caption: p.caption, share_to_feed: String(p.shareToFeed), thumb_offset: p.coverAtMs, access_token: c.token,
    }, p.coverUrl ? { cover_url: p.coverUrl } : {}, byUrl ? { video_url: p.video.url } : { upload_type: 'resumable' }));
    s.containerId = r.id;
    s.byUrl = byUrl;
    s.uploadUrl = byUrl ? null : r.uri || `https://rupload.facebook.com/ig-api-upload/${GRAPH_VERSION}/${r.id}`;
    delete s.processSince;
    delete s.uploadDoubt;
    ctx.save();
    return 'next';
  },

  /**
   * A failed upload leaves the container unusable ("not in the status to upload a video"), so the
   * next try starts again with a fresh container instead of resuming into the old one.
   * Meta's upload host answers about two in three whole Reel uploads with ProcessingFailedError. A few of
   * those containers still go on to FINISHED, so the process step waits for that; most never do, and
   * then the job starts again with a new container.
   */
  upload(p, s, ctx, c) {
    if (!s.containerId) IG_STEPS.container(p, s, ctx, c);
    if (s.byUrl) return 'next';
    metaFileSize_(p, s);
    try {
      return metaSendFile_(p, s, ctx, s.uploadUrl, c.token);
    } catch (err) {
      if (/ProcessingFailedError/.test(err.message) && s.offset + CHUNK_BYTES >= s.size) {
        s.offset = s.size;
        s.uploadDoubt = true;
        ctx.save();
        return 'next';
      }
      delete s.containerId;
      delete s.uploadUrl;
      s.offset = 0;
      ctx.save();
      throw err;
    }
  },

  /**
   * Instagram processes the video before it can be published; this usually takes under a minute.
   * A container that will never finish (a link Instagram could not fetch, an upload that never arrived)
   * is dropped and the job tries again from the start, up to MAX_ATTEMPTS times.
   */
  process(p, s, ctx, c) {
    if (!s.containerId) { igStartOver_(s, ctx); throw new ApiError('upstream', 'The Instagram container was lost; starting again', { retry: 'transient' }); }
    if (!s.processSince) { s.processSince = Date.now(); ctx.save(); }
    const began = Date.now();
    for (;;) {
      let r;
      try {
        // video_status exists only on an uploaded container; asking a linked one for it is an error (100/2207065).
        r = metaGet_(`/${s.containerId}`, { fields: s.byUrl ? 'status_code,status' : 'status_code,status,video_status', access_token: c.token });
      } catch (err) {
        // Meta deletes a container whose upload never arrived; asking for it then answers code 100, subcode 33.
        if (!err.details || err.details.reason !== 100 || err.details.subcode !== 33) throw err;
        igStartOver_(s, ctx);
        throw new ApiError('upstream', `Instagram dropped the container before the video arrived; starting again (${err.message})`, { retry: 'transient' });
      }
      if (r.status_code === 'FINISHED' || r.status_code === 'PUBLISHED') {
        // After a ProcessingFailedError, FINISHED is Instagram's own word that the video is ready; its
        // bytes_transferred counter can read 0 by then, so it is only noted, and publish decides.
        if (s.uploadDoubt) ctx.warn(`Upload answered ProcessingFailedError; Instagram still finished processing (${JSON.stringify(r.video_status || null).slice(0, 200)})`);
        return 'next';
      }
      if (r.status_code === 'ERROR' || r.status_code === 'EXPIRED') {
        const why = `${r.status_code}): ${r.status || 'no reason given'}`;
        if (s.byUrl && p.video.driveFileId) {
          s.urlFailed = why;
          igStartOver_(s, ctx);
          throw new ApiError('upstream', `Instagram could not take the video from its link (${why}. Uploading the Drive file instead`, { retry: 'transient' });
        }
        throw new ApiError('upstream', `Instagram could not process the video (${why}. Reels must be MP4/MOV, 3 s to 15 min, 9:16 works best.`);
      }
      const limit = s.uploadDoubt ? IG_DOUBT_MS : IG_PROCESS_MS;
      if (Date.now() - s.processSince > limit) {
        const what = s.uploadDoubt ? 'Instagram refused the upload (ProcessingFailedError) and' : 'Instagram';
        igStartOver_(s, ctx);
        throw new ApiError('upstream', `${what} did not finish processing the video within ${Math.round(limit / 60000)} minutes; starting again with a new container`, { retry: 'transient' });
      }
      if (ctx.outOfTime()) return 'pause';
      if (Date.now() - began > IG_POLL_MS) return 'wait'; // other jobs go first; the worker comes back to this one
      Utilities.sleep(10 * 1000);
    }
  },

  publish(p, s, ctx, c) {
    if (s.videoId) return 'next';
    s.videoId = metaPost_(`/${c.igId}/media_publish`, { creation_id: s.containerId, access_token: c.token }).id;
    ctx.save();
    return 'next';
  },

  check(p, s, ctx, c) {
    const r = metaGet_(`/${s.videoId}`, { fields: 'permalink,shortcode,timestamp', access_token: c.token });
    if (s.urlFailed) ctx.warn(`Instagram could not take the video from its link (${s.urlFailed}; the file was uploaded from Drive instead`);
    ctx.result({ mediaId: s.videoId, url: r.permalink || null, publishedAt: r.timestamp || null });
    return 'next';
  },
};

// ---- src/facebook.js ----
/**
 * Facebook adapter: posts a video from Drive as a Reel on the connected Facebook Page (see src/meta.js).
 * It can publish now, schedule with publishAt, or leave the Reel as a draft with "state": "draft".
 */

const FB_STATES = ['published', 'draft'];

const Facebook = {
  name: 'facebook',
  /** Our own caps: Meta documents no Reel limit, and these leave room. */
  limits: { title: 100, description: 5000 },

  validate(p, now) {
    const video = optFile_(p.video, 'video');
    if (!video) throw new ApiError('invalid', 'Send video: {"driveFileId": ...}');
    const state = optText_(p.state, 'state', 20) || 'published';
    if (!FB_STATES.includes(state)) throw new ApiError('invalid', `state must be one of ${FB_STATES.join(', ')}`);
    const publishAt = optFutureTime_(p.publishAt, 'publishAt', now);
    if (publishAt && state === 'draft') throw new ApiError('invalid', 'Send publishAt or "state": "draft", not both');
    const description = optText_(p.description, 'description', Facebook.limits.description);
    return {
      video, description, state, publishAt,
      title: optText_(p.title, 'title', Facebook.limits.title) || (description || '').split('\n')[0].slice(0, Facebook.limits.title),
    };
  },

  steps() {
    return ['start', 'upload', 'finish', 'check'];
  },

  run(step, job, ctx) {
    return FB_STEPS[step](job.post, job.state, ctx, metaConfig_(false));
  },

  /** Page followers and the newest Reels with likes, comments and plays (plays need read_insights). */
  stats(limit) {
    const c = metaConfig_(false);
    const page = metaGet_(`/${c.pageId}`, { fields: 'followers_count,fan_count', access_token: c.token });
    const reels = metaGet_(`/${c.pageId}/video_reels`, {
      fields: 'id,permalink_url,description,created_time,likes.summary(true).limit(0),comments.summary(true).limit(0)', limit, access_token: c.token,
    }).data || [];
    const ins = metaInsightsEach_(reels, (v) => metaGet_(`/${v.id}/video_insights`, { metric: 'blue_reels_play_count,post_impressions_unique', access_token: c.token }));
    const total = (x) => (x && x.summary && x.summary.total_count != null ? x.summary.total_count : null);
    const followers = page.followers_count != null ? page.followers_count : page.fan_count;
    return {
      followers: followers == null ? null : followers,
      posts: reels.map((v, i) => ({
        url: /^https?:/.test(v.permalink_url || '') ? v.permalink_url : `https://www.facebook.com${v.permalink_url || `/reel/${v.id}`}`,
        title: firstLine_(v.description), at: v.created_time, likes: total(v.likes), comments: total(v.comments),
        views: ins[i] && metaMetric_(ins[i], 'blue_reels_play_count'), reach: ins[i] && metaMetric_(ins[i], 'post_impressions_unique'),
      })),
    };
  },

  /** Newest comments on the Page's newest Reels, minus the Page's own, with whether the Page replied (needs pages_read_user_content). */
  comments(limit) {
    const c = metaConfig_(false);
    const reels = (metaGet_(`/${c.pageId}/video_reels`, {
      fields: 'id,permalink_url,description,comments.summary(true).limit(0)', limit: 25, access_token: c.token,
    }).data || []).filter((v) => v.comments && v.comments.summary && v.comments.summary.total_count);
    const out = [];
    reels.forEach((v) => {
      const list = metaGet_(`/${v.id}/comments`, {
        fields: 'id,message,from,created_time,like_count,comments{from,message}', filter: 'toplevel', order: 'reverse_chronological', limit: 50, access_token: c.token,
      }).data || [];
      list.filter((x) => !(x.from && x.from.id === c.pageId)).forEach((x) => {
        const replies = (x.comments && x.comments.data) || [];
        out.push({
          id: x.id, author: (x.from && x.from.name) || 'Facebook user', text: x.message, at: x.created_time, likes: x.like_count == null ? 0 : x.like_count,
          videoId: v.id, videoTitle: firstLine_(v.description),
          url: /^https?:/.test(v.permalink_url || '') ? v.permalink_url : `https://www.facebook.com${v.permalink_url || `/reel/${v.id}`}`,
          replies: replies.length, replied: replies.some((r) => r.from && r.from.id === c.pageId),
        });
      });
    });
    out.sort((a, b) => String(b.at).localeCompare(String(a.at)));
    return { comments: out.slice(0, limit) };
  },

  /** Replies to a comment as the Page. Sending the same text again returns the first reply instead of posting twice. */
  reply(commentId, text) {
    const c = metaConfig_(false);
    const id = encodeURIComponent(commentId);
    const mine = (metaGet_(`/${id}/comments`, { fields: 'id,message,from', limit: 100, access_token: c.token }).data || [])
      .find((x) => x.from && x.from.id === c.pageId && x.message === text);
    const r = mine || metaPost_(`/${id}/comments`, { message: text, access_token: c.token });
    return { reply: { id: r.id, commentId, text, existing: !!mine } };
  },

  whoami() {
    const c = metaConfig_(false);
    const r = metaGet_(`/${c.pageId}`, { fields: 'name,link', access_token: c.token });
    return { id: c.pageId, title: r.name, url: r.link || `https://www.facebook.com/${c.pageId}` };
  },
};

const FB_STEPS = {
  start(p, s, ctx, c) {
    if (s.reelId) return 'next';
    const r = metaPost_(`/${c.pageId}/video_reels`, { upload_phase: 'start', access_token: c.token });
    s.reelId = r.video_id;
    s.uploadUrl = r.upload_url || `https://rupload.facebook.com/video-upload/${GRAPH_VERSION}/${r.video_id}`;
    ctx.save();
    return 'next';
  },

  upload(p, s, ctx, c) {
    metaFileSize_(p, s);
    return metaSendFile_(p, s, ctx, s.uploadUrl, c.token);
  },

  finish(p, s, ctx, c) {
    if (s.videoId) return 'next';
    metaPost_(`/${c.pageId}/video_reels`, {
      upload_phase: 'finish', video_id: s.reelId, access_token: c.token,
      video_state: p.publishAt ? 'SCHEDULED' : p.state.toUpperCase(),
      scheduled_publish_time: p.publishAt ? Math.floor(new Date(p.publishAt).getTime() / 1000) : null,
      description: p.description, title: p.title || null,
    });
    s.videoId = s.reelId;
    ctx.save();
    return 'next';
  },

  /** Waits for Facebook to finish processing, so a broken video shows up as a failed job. */
  check(p, s, ctx, c) {
    for (;;) {
      const r = metaGet_(`/${s.videoId}`, { fields: 'status,permalink_url', access_token: c.token });
      const st = r.status || {};
      const phases = [st.uploading_phase, st.processing_phase, st.publishing_phase].filter(Boolean);
      const bad = phases.find((x) => x.status === 'error');
      if (st.video_status === 'error' || bad) {
        throw new ApiError('upstream', `Facebook could not process the Reel: ${(bad && bad.errors && bad.errors[0] && bad.errors[0].message) || 'no reason given'}`);
      }
      if (st.video_status === 'ready' || (st.publishing_phase && st.publishing_phase.status === 'complete') || p.state === 'draft' || p.publishAt) {
        const link = r.permalink_url ? (r.permalink_url.startsWith('http') ? r.permalink_url : `https://www.facebook.com${r.permalink_url}`) : `https://www.facebook.com/reel/${s.videoId}`;
        ctx.result({ videoId: s.videoId, url: link, state: p.publishAt ? 'scheduled' : p.state, publishAt: p.publishAt || null, videoStatus: st.video_status || null });
        return 'next';
      }
      if (ctx.outOfTime()) return 'pause';
      Utilities.sleep(10 * 1000);
    }
  },
};

// ---- src/linkedin.js ----
/**
 * LinkedIn adapter. Posts a video from Drive to the signed-in member's LinkedIn profile with the
 * self-serve "Share on LinkedIn" product (scope w_member_social): upload the video in 4 MB parts
 * (across several worker runs if needed), finalize it, wait until LinkedIn has processed it, then post it.
 *
 * Sign-in needs two Script Properties from the LinkedIn developer app: LI_CLIENT_ID and LI_CLIENT_SECRET,
 * with the redirect URL https://script.google.com/macros/d/<script id>/usercallback added to the app.
 * Run connectLinkedIn() in the editor and open the link it logs. LinkedIn tokens last 60 days and
 * self-serve apps get no refresh token, so the sign-in has to be repeated before LI_EXPIRES_AT.
 */

const LI = 'https://api.linkedin.com';
const LI_VERSION = '202610'; // LinkedIn retires each version after about a year; bump it when a newer one is out.
const LI_VISIBILITY = ['PUBLIC', 'CONNECTIONS', 'LOGGED_IN'];
const LI_SCOPES = ['openid', 'profile', 'w_member_social'];
let LI_MIN_BYTES = 75 * 1024;

const LinkedIn = {
  name: 'linkedin',
  limits: { text: 3000, title: 200 },

  validate(p) {
    const video = optFile_(p.video, 'video');
    if (!video) throw new ApiError('invalid', 'Send video: {"driveFileId": ...}');
    const text = optText_(p.text !== undefined ? p.text : p.description, 'text', LinkedIn.limits.text);
    const title = optText_(p.title, 'title', LinkedIn.limits.title);
    let visibility = optText_(p.visibility, 'visibility', 20) || 'PUBLIC';
    visibility = visibility.toUpperCase();
    if (!LI_VISIBILITY.includes(visibility)) throw new ApiError('invalid', `visibility must be one of ${LI_VISIBILITY.join(', ')}`);
    if (p.publishAt) throw new ApiError('invalid', 'LinkedIn posts go out straight away; publishAt is not supported. Send the request at the time you want it posted.');
    return { video, title, text: text || '', visibility, thumbnail: optFile_(p.thumbnail, 'thumbnail') };
  },

  steps() {
    return ['upload', 'finalize', 'wait', 'post'];
  },

  run(step, job, ctx) {
    return LI_STEPS[step](job.post, job.state, ctx);
  },

  /** The member the service posts as, and when the sign-in runs out. */
  whoami() {
    const u = liJson_('get', `${LI}/v2/userinfo`, null, true);
    return { id: `urn:li:person:${u.sub}`, title: u.name, tokenExpiresAt: props_().getProperty('LI_EXPIRES_AT') || null };
  },
};

const LI_STEPS = {
  upload(p, s, ctx) {
    if (!s.size) {
      const m = driveMeta_(p.video.driveFileId);
      s.size = Number(m.size);
      if (s.size < LI_MIN_BYTES || s.size > 500 * 1024 * 1024) throw new ApiError('invalid', `LinkedIn takes videos from 75 KB to 500 MB; this one is ${s.size} bytes`);
    }
    if (!s.uploadToken) {
      s.author = liAuthor_();
      const r = liJson_('post', `${LI}/rest/videos?action=initializeUpload`, {
        initializeUploadRequest: { owner: s.author, fileSizeBytes: s.size, uploadCaptions: false, uploadThumbnail: !!p.thumbnail },
      }).value;
      s.videoUrn = r.video;
      s.uploadToken = r.uploadToken || '';
      s.parts = r.uploadInstructions.map((x) => ({ a: x.firstByte, b: x.lastByte, url: x.uploadUrl }));
      s.thumbUrl = r.thumbnailUploadUrl || null;
      s.etags = [];
      s.offset = 0;
      ctx.save();
    }
    while (s.etags.length < s.parts.length) {
      if (ctx.outOfTime()) return 'pause';
      const part = s.parts[s.etags.length];
      const r = UrlFetchApp.fetch(part.url, {
        method: 'put', muteHttpExceptions: true, contentType: 'application/octet-stream',
        payload: driveRange_(p.video.driveFileId, part.a, part.b),
      });
      if (r.getResponseCode() >= 300) throw liError_(r);
      s.etags.push(String(header_(r, 'ETag')).replace(/"/g, ''));
      s.offset = part.b + 1;
      ctx.save();
    }
    if (s.thumbUrl && !s.thumbDone) {
      ctx.optional('thumbnail', () => {
        const m = driveMeta_(p.thumbnail.driveFileId);
        const r = UrlFetchApp.fetch(s.thumbUrl, {
          method: 'put', muteHttpExceptions: true, contentType: m.mimeType || 'image/jpeg',
          headers: { 'media-type-family': 'STILLIMAGE' }, payload: driveBytes_(p.thumbnail.driveFileId),
        });
        if (r.getResponseCode() >= 300) throw liError_(r);
      });
      s.thumbDone = true;
    }
    return 'next';
  },

  finalize(p, s) {
    liJson_('post', `${LI}/rest/videos?action=finalizeUpload`, {
      finalizeUploadRequest: { video: s.videoUrn, uploadToken: s.uploadToken, uploadedPartIds: s.etags },
    });
    return 'next';
  },

  /** LinkedIn processes the video before it can be posted; that usually takes under a minute. */
  wait(p, s) {
    for (let i = 0; i < 6; i++) {
      const v = liJson_('get', `${LI}/rest/videos/${encodeURIComponent(s.videoUrn)}`);
      if (v.status === 'AVAILABLE') return 'next';
      if (v.status === 'PROCESSING_FAILED') throw new ApiError('upstream', `LinkedIn could not process the video: ${v.processingFailureReason || 'no reason given'}`);
      Utilities.sleep(10 * 1000);
    }
    return 'pause';
  },

  post(p, s, ctx) {
    if (!s.postUrn) {
      const r = liFetch_('post', `${LI}/rest/posts`, {
        author: s.author,
        commentary: liText_(p.text),
        visibility: p.visibility,
        distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
        content: { media: { id: s.videoUrn, title: p.title || undefined } },
        lifecycleState: 'PUBLISHED',
        isReshareDisabledByAuthor: false,
      });
      if (r.getResponseCode() !== 201) throw liError_(r);
      s.postUrn = header_(r, 'x-restli-id');
      ctx.save();
    }
    ctx.result({ postUrn: s.postUrn, videoUrn: s.videoUrn, url: `https://www.linkedin.com/feed/update/${s.postUrn}/`, visibility: p.visibility });
    const left = liDaysLeft_();
    if (left !== null && left < 10) ctx.warn(`The LinkedIn sign-in runs out in ${left} days; run connectLinkedIn() again.`);
    return 'next';
  },
};

/**
 * LinkedIn's post text is "little text": these characters must be backslash-escaped or the post is
 * cut short. #words are turned into real hashtags.
 */
function liText_(t) {
  return String(t || '').split(/(#[\p{L}\p{N}_]+)/u).map((part, i) => (i % 2
    ? `{hashtag|\\#|${part.slice(1)}}`
    : part.replace(/[\\|{}@[\]()<>#*_~]/g, (c) => `\\${c}`))).join('');
}

function liAuthor_() {
  const p = props_();
  let id = p.getProperty('LI_PERSON');
  if (!id) { id = LinkedIn.whoami().id; p.setProperty('LI_PERSON', id); }
  return id;
}

function liDaysLeft_() {
  const at = props_().getProperty('LI_EXPIRES_AT');
  return at ? Math.floor((new Date(at).getTime() - Date.now()) / 86400000) : null;
}

function liFetch_(method, url, json, plain) {
  const token = props_().getProperty('LI_ACCESS_TOKEN');
  if (!token) throw new ApiError('invalid', 'LinkedIn is not connected; run connectLinkedIn() in the script editor (see the FAQ)');
  const headers = { Authorization: `Bearer ${token}` };
  if (!plain) { headers['LinkedIn-Version'] = LI_VERSION; headers['X-Restli-Protocol-Version'] = '2.0.0'; }
  const o = { method, muteHttpExceptions: true, headers };
  if (json) { o.contentType = 'application/json'; o.payload = JSON.stringify(json); }
  return UrlFetchApp.fetch(url, o);
}

function liJson_(method, url, json, plain) {
  const r = liFetch_(method, url, json, plain);
  if (r.getResponseCode() >= 300) throw liError_(r);
  const text = r.getContentText();
  return text ? JSON.parse(text) : {};
}

function liError_(r) {
  const code = r.getResponseCode();
  let message = '';
  try { message = JSON.parse(r.getContentText()).message || ''; } catch (err) { message = String(r.getContentText()).slice(0, 300); }
  if (code === 401) message = `${message} (the LinkedIn sign-in has run out or was revoked; run connectLinkedIn() again)`;
  let retry = false;
  if (code === 429) retry = 'quota';
  else if (code >= 500) retry = 'transient';
  return new ApiError('upstream', `LinkedIn answered ${code}: ${message}`, { status: code, retry });
}

// ---------- sign-in ----------

/** Logs the LinkedIn sign-in link. Open it and press Allow. */
function connectLinkedIn() {
  const p = props_();
  if (!p.getProperty('LI_CLIENT_ID') || !p.getProperty('LI_CLIENT_SECRET')) {
    throw new Error('Add the LI_CLIENT_ID and LI_CLIENT_SECRET script properties first (see the FAQ).');
  }
  const state = ScriptApp.newStateToken().withMethod('linkedInCallback').withTimeout(600).createToken();
  const q = { response_type: 'code', client_id: p.getProperty('LI_CLIENT_ID'), redirect_uri: ytRedirectUri_(), scope: LI_SCOPES.join(' '), state };
  const url = `https://www.linkedin.com/oauth/v2/authorization?${Object.keys(q).map((k) => `${k}=${encodeURIComponent(q[k])}`).join('&')}`;
  console.log(`Open this link and press Allow (valid 10 minutes):\n${url}`);
  return url;
}

function linkedInCallback(req) {
  const p = props_();
  const r = UrlFetchApp.fetch('https://www.linkedin.com/oauth/v2/accessToken', {
    method: 'post', muteHttpExceptions: true,
    payload: {
      grant_type: 'authorization_code', code: req.parameter.code, redirect_uri: ytRedirectUri_(),
      client_id: p.getProperty('LI_CLIENT_ID'), client_secret: p.getProperty('LI_CLIENT_SECRET'),
    },
  });
  const t = JSON.parse(r.getContentText());
  if (!t.access_token) return HtmlService.createHtmlOutput(`Sign-in failed: ${String(t.error_description || t.error || r.getResponseCode())}`);
  p.setProperty('LI_ACCESS_TOKEN', t.access_token);
  p.setProperty('LI_EXPIRES_AT', new Date(Date.now() + Number(t.expires_in || 0) * 1000).toISOString());
  p.deleteProperty('LI_PERSON');
  let who = '';
  try { who = LinkedIn.whoami().title; } catch (err) { who = `(could not read the profile: ${err.message})`; }
  return HtmlService.createHtmlOutput(`Connected. Social Media Publisher now posts to LinkedIn as: ${who}. The sign-in lasts until ${p.getProperty('LI_EXPIRES_AT')}. You can close this tab.`);
}

// ---- src/store.js ----
/**
 * Jobs live in the "Jobs" tab of the Social Media Publisher spreadsheet, one row each, so the owner can read them.
 */

const JOB_COLS = ['id', 'key', 'platform', 'status', 'title', 'attempts', 'notBefore', 'createdAt', 'updatedAt', 'caller', 'result', 'error', 'post', 'state'];
const JSON_COLS = ['result', 'post', 'state'];

function props_() {
  return PropertiesService.getScriptProperties();
}

function jobsSheet_() {
  const id = props_().getProperty('SHEET_ID');
  if (!id) throw new ApiError('not_set_up', 'Run setup() in the Apps Script editor first');
  return SpreadsheetApp.openById(id).getSheetByName('Jobs');
}

function withLock_(fn) {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(20000)) throw new ApiError('busy', 'The service is busy; try again in a few seconds', { retry: 'transient' });
  try { return fn(); } finally { lock.releaseLock(); }
}

function rowToJob_(row) {
  const j = {};
  JOB_COLS.forEach((c, i) => {
    const v = row[i];
    j[c] = JSON_COLS.includes(c) ? (v ? JSON.parse(v) : null) : (v === '' ? null : v);
  });
  j.attempts = Number(j.attempts || 0);
  j.state = j.state || {};
  return j;
}

function jobToRow_(j) {
  return JOB_COLS.map((c) => {
    const v = j[c];
    if (JSON_COLS.includes(c)) return v ? JSON.stringify(v) : '';
    return v === null || v === undefined ? '' : v;
  });
}

function allJobs_() {
  const sh = jobsSheet_();
  const n = sh.getLastRow() - 1;
  if (n < 1) return [];
  return sh.getRange(2, 1, n, JOB_COLS.length).getValues().filter((r) => r[0]).map(rowToJob_);
}

function findJob_(id) {
  const sh = jobsSheet_();
  const n = sh.getLastRow() - 1;
  if (n < 1) return null;
  const hit = sh.getRange(2, 1, n, 1).createTextFinder(String(id)).matchEntireCell(true).findNext();
  if (!hit) return null;
  return { row: hit.getRow(), job: rowToJob_(sh.getRange(hit.getRow(), 1, 1, JOB_COLS.length).getValues()[0]) };
}

function jobOrThrow_(id) {
  const f = findJob_(id);
  if (!f) throw new ApiError('not_found', `No job ${id}`);
  return f;
}

function insertJob_(job) {
  jobsSheet_().appendRow(jobToRow_(job));
}

function saveJob_(job) {
  job.updatedAt = new Date().toISOString();
  withLock_(() => {
    const f = jobOrThrow_(job.id);
    jobsSheet_().getRange(f.row, 1, 1, JOB_COLS.length).setValues([jobToRow_(job)]);
  });
}

// ---- src/worker.js ----
/**
 * The worker: a time trigger runs runQueue every 5 minutes and works through queued jobs one at a time.
 * Long uploads stop before Apps Script's time limit and carry on in the next run.
 * A step that is only waiting on its platform answers 'wait': the job steps aside for WAIT_MS, so the
 * jobs behind it are not held up, and the same run comes back to it when it has time left.
 */

let WAIT_MS = 15 * 1000;

function runQueue() {
  return runQueue_();
}

function runQueue_() {
  const p = props_();
  // Only one worker at a time. A crashed worker's claim runs out after 7 minutes.
  const claimed = withLock_(() => {
    if (Number(p.getProperty('WORKER_UNTIL') || 0) > Date.now()) return false;
    p.setProperty('WORKER_UNTIL', String(Date.now() + 7 * 60 * 1000));
    return true;
  });
  if (!claimed) return { ran: [], note: 'Another worker run is busy' };
  const started = Date.now();
  let ran = [];
  try {
    do {
      const jobs = allJobs_();
      const job = pickNextJob_(jobs, new Date());
      if (!job) {
        // Nothing to do now. If a queued job is due again within this run's time, wait for it.
        const due = jobs.filter((j) => j.status === 'queued' && j.notBefore).map((j) => new Date(j.notBefore).getTime()).sort((a, b) => a - b)[0];
        if (!due || due - started >= WORK_BUDGET_MS) break;
        Utilities.sleep(Math.max(due - Date.now(), 0) + 20);
        continue;
      }
      const paused = runJob_(job, started) === 'paused';
      ran = ran.filter((j) => j.id !== job.id).concat(presentJob_(job));
      if (paused) break; // out of time mid-upload; the next run carries on
    } while (Date.now() - started < WORK_BUDGET_MS);
  } finally {
    p.deleteProperty('WORKER_UNTIL');
  }
  return { ran };
}

function runJob_(job, started) {
  const adapter = adapterFor_(job.platform);
  ACCOUNT = (job.post && job.post.account) || ''; // each job works as its own channel or Page
  const steps = adapter.steps(job.post);
  job.status = 'running';
  job.notBefore = null;
  const warnings = (job.result && job.result.warnings) || [];
  const ctx = {
    outOfTime: () => Date.now() - started > WORK_BUDGET_MS,
    save: () => saveJob_(job),
    warn: (msg) => { if (!warnings.includes(msg)) warnings.push(msg); },
    result: (r) => { job.result = Object.assign({}, r, { warnings }); },
    /** For extras (thumbnail, captions, playlists): a failure that a retry can't fix becomes a warning, not a failed job. */
    optional: (what, fn) => {
      try { fn(); } catch (err) {
        if (err && err.details && err.details.retry) throw err;
        ctx.warn(`${what}: ${err && err.message ? err.message : err}`);
      }
    },
  };
  saveJob_(job);
  try {
    for (let i = job.state.stepIndex || 0; i < steps.length; i++) {
      job.state.step = steps[i];
      const answer = adapter.run(steps[i], job, ctx);
      if (answer === 'pause' || answer === 'wait') {
        job.status = 'queued';
        if (answer === 'wait') job.notBefore = new Date(Date.now() + WAIT_MS).toISOString();
        saveJob_(job);
        return answer === 'wait' ? 'waiting' : 'paused';
      }
      job.state.stepIndex = i + 1;
      saveJob_(job);
    }
    job.status = 'done';
    job.error = null;
    if (!job.result) job.result = { warnings };
  } catch (err) {
    console.error(err && err.stack ? err.stack : err);
    Object.assign(job, afterError_(job, err, new Date()));
    // Name the step, so a caller can tell an upload error from a publish error.
    if (job.error && job.state.step) job.error = `${job.state.step} step: ${job.error}`;
  }
  saveJob_(job);
}

// ---- src/api.js ----
/**
 * Web app entry points and the API actions.
 *
 * Every call: GET ?action=...&token=... or POST with a JSON body {"action": ..., "token": ..., ...}.
 * Apps Script always answers HTTP 200, so success or failure is in the body:
 *   {"ok": true, ...}  or  {"ok": false, "error": {"code": "...", "message": "...", "details": {...}}}
 */

function doGet(e) { return handle_(e, 'GET'); }
function doPost(e) { return handle_(e, 'POST'); }

const ROUTES = {
  health: { auth: false, fn: health_ },
  platforms: { fn: platformsInfo_ },
  channel: { fn: (req) => adapterFor_(req.platform || 'youtube').whoami() },
  stats: { fn: (req) => stats_(req) },
  comments: { fn: (req) => comments_(req) },
  reply: { write: true, fn: reply_ },
  publish: { write: true, fn: publish_ },
  connectYouTube: { write: true, admin: true, fn: (req) => ({ url: connectYouTube(req.account || ''), account: req.account || null }) },
  connectMeta: { write: true, admin: true, fn: (req) => ({ url: connectMeta(req.account || '', req.match || ''), account: req.account || null }) },
  get: { fn: (req) => ({ job: presentJob_(jobByIdOrKey_(req)) }) },
  list: { fn: list_ },
  retry: { write: true, fn: retry_ },
  cancel: { write: true, fn: cancel_ },
  run: { write: true, admin: true, fn: () => runQueue_() },
  deploy: { write: true, admin: true, fn: (req) => deployLatest_(req.force === true, req.ref) },
  createToken: { write: true, admin: true, fn: createToken_ },
  revokeToken: { write: true, admin: true, fn: revokeToken_ },
  listTokens: { admin: true, fn: listTokens_ },
};

function handle_(e, method) {
  try {
    const req = parseRequest_(e, method);
    const route = ROUTES[req.action || 'health'];
    if (!route) throw new ApiError('unknown_action', `Unknown action "${req.action}". Actions: ${Object.keys(ROUTES).join(', ')}`);
    if (route.write && method !== 'POST') throw new ApiError('method_not_allowed', `${req.action} needs POST`);
    const caller = route.auth === false ? null : authenticate_(req.token);
    if (route.admin && !caller.admin) throw new ApiError('forbidden', 'This action needs an admin token.');
    ACCOUNT = accountName_(req.account);
    return json_(Object.assign({ ok: true }, route.fn(req, caller)));
  } catch (err) {
    if (err instanceof ApiError) {
      return json_({ ok: false, error: { code: err.code, message: err.message, details: err.details || null } });
    }
    console.error(err && err.stack ? err.stack : err);
    return json_({ ok: false, error: { code: 'internal', message: String(err && err.message ? err.message : err), details: null } });
  }
}

function parseRequest_(e, method) {
  const req = Object.assign({}, (e && e.parameter) || {});
  if (method === 'POST' && e && e.postData && e.postData.contents) {
    let body;
    try { body = JSON.parse(e.postData.contents); } catch (err) { throw new ApiError('bad_json', 'The POST body must be JSON.'); }
    if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ApiError('bad_json', 'The POST body must be a JSON object.');
    Object.assign(req, body);
  }
  return req;
}

function json_(o) {
  return ContentService.createTextOutput(JSON.stringify(o)).setMimeType(ContentService.MimeType.JSON);
}

// ---------- auth: tokens are stored only as SHA-256 hashes in Script Properties ----------

function sha256Hex_(s) {
  return Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, String(s), Utilities.Charset.UTF_8)
    .map((b) => ((b + 256) % 256).toString(16).padStart(2, '0')).join('');
}

function tokens_() {
  return JSON.parse(props_().getProperty('TOKENS') || '{}');
}

function authenticate_(token) {
  if (!token) throw new ApiError('unauthorized', 'token is required');
  const entry = tokens_()[sha256Hex_(token)];
  if (!entry) throw new ApiError('unauthorized', 'Unknown or revoked token');
  return entry;
}

/** Creates a token for a named client. The plain token is returned once and never stored. */
function issueToken_(name, admin) {
  if (!NAME_RE.test(String(name || ''))) throw new ApiError('invalid', 'name must be lowercase letters, digits or dashes (max 40)');
  const all = tokens_();
  if (Object.keys(all).some((h) => all[h].name === name)) throw new ApiError('conflict', `A token named ${name} exists; revoke it first`);
  const token = Utilities.getUuid().replace(/-/g, '') + Utilities.getUuid().replace(/-/g, '');
  all[sha256Hex_(token)] = { name, admin: !!admin, createdAt: new Date().toISOString() };
  props_().setProperty('TOKENS', JSON.stringify(all));
  return token;
}

function createToken_(req) {
  return withLock_(() => ({ name: req.name, admin: req.admin === true, token: issueToken_(req.name, req.admin === true) }));
}

function revokeToken_(req, caller) {
  return withLock_(() => {
    const all = tokens_();
    const hashes = Object.keys(all).filter((h) => all[h].name === req.name);
    if (!hashes.length) throw new ApiError('not_found', `No token named ${req.name}`);
    if (req.name === caller.name) throw new ApiError('invalid', 'You cannot revoke the token you are calling with');
    hashes.forEach((h) => { delete all[h]; });
    props_().setProperty('TOKENS', JSON.stringify(all));
    return { revoked: req.name };
  });
}

function listTokens_() {
  const all = tokens_();
  return { tokens: Object.keys(all).map((h) => all[h]) };
}

// ---------- jobs ----------

function health_() {
  return { service: 'social-media-publisher', version: API_VERSION, platforms: Object.keys(platforms_()), time: new Date().toISOString() };
}

/** Followers and the newest posts' numbers on one platform, for platforms whose adapter has stats(). */
function stats_(req) {
  const name = String(req.platform || '');
  const a = adapterFor_(name);
  if (typeof a.stats !== 'function') throw new ApiError('invalid', `${name} has no stats yet. Platforms with stats: ${Object.keys(platforms_()).filter((k) => platforms_()[k].stats).join(', ')}`);
  const limit = Math.min(Math.max(Number(req.limit) || 25, 1), 100);
  return Object.assign({ platform: name }, a.stats(limit));
}

function comments_(req) {
  const name = String(req.platform || '');
  const a = adapterFor_(name);
  if (typeof a.comments !== 'function') throw new ApiError('invalid', `${name} has no comments yet. Platforms with comments: ${Object.keys(platforms_()).filter((k) => platforms_()[k].comments).join(', ')}`);
  const limit = Math.min(Math.max(Number(req.limit) || 20, 1), 100);
  return Object.assign({ platform: name }, a.comments(limit));
}

function reply_(req) {
  const name = String(req.platform || '');
  const a = adapterFor_(name);
  if (typeof a.reply !== 'function') throw new ApiError('invalid', `${name} cannot reply to comments yet`);
  const commentId = optText_(req.commentId, 'commentId', 200);
  const text = optText_(req.text, 'text', 10000);
  if (!commentId || !text) throw new ApiError('invalid', 'Send commentId and text');
  return Object.assign({ platform: name }, a.reply(commentId, text));
}

function platformsInfo_() {
  const all = platforms_();
  const limits = {};
  Object.keys(all).forEach((k) => { limits[k] = all[k].limits || {}; });
  return { platforms: Object.keys(all), limits };
}

function jobByIdOrKey_(req) {
  if (req.id) return jobOrThrow_(req.id).job;
  if (req.key) {
    const j = allJobs_().filter((x) => x.key === String(req.key) && x.status !== 'cancelled').pop();
    if (!j) throw new ApiError('not_found', `No job with key ${req.key}`);
    return j;
  }
  throw new ApiError('invalid', 'Send id or key');
}

/**
 * Queues a post. With a key, sending the same post again returns the first job instead of posting twice,
 * so a caller can safely retry after a timeout.
 */
function publish_(req, caller) {
  const adapter = adapterFor_(req.platform);
  const now = new Date();
  const post = adapter.validate(req, now);
  if (adapter.name === 'youtube' && ACCOUNT) {
    if (!ytAccountConnected_(ACCOUNT)) throw new ApiError('not_connected', `The YouTube account "${ACCOUNT}" is not connected; call connectYouTube with that account first`);
    post.account = ACCOUNT;
  }
  if ((adapter.name === 'instagram' || adapter.name === 'facebook') && ACCOUNT) {
    if (!metaConnected_(ACCOUNT)) throw new ApiError('not_connected', `The Meta account "${ACCOUNT}" is not connected; call connectMeta with that account first`);
    post.account = ACCOUNT;
  }
  const key = optText_(req.key, 'key', 100);
  return withLock_(() => {
    if (key) {
      const prior = allJobs_().find((j) => j.key === key && j.status !== 'cancelled');
      if (prior) return { job: presentJob_(prior), existing: true };
    }
    const iso = now.toISOString();
    const job = {
      id: newJobId_(now, Utilities.getUuid().slice(0, 4)), key, platform: adapter.name, status: 'queued',
      title: post.title || post.videoId || '', attempts: 0, notBefore: post.notBefore || null, createdAt: iso, updatedAt: iso,
      caller: caller.name, result: null, error: null, post, state: {},
    };
    insertJob_(job);
    return { job: presentJob_(job), existing: false };
  });
}

function list_(req) {
  if (req.status && !JOB_STATUSES.includes(req.status)) throw new ApiError('invalid', `status must be one of ${JOB_STATUSES.join(', ')}`);
  const limit = Math.min(Math.max(Number(req.limit) || 20, 1), 200);
  const jobs = allJobs_()
    .filter((j) => (!req.status || j.status === req.status) && (!req.platform || j.platform === req.platform))
    .sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))
    .slice(0, limit);
  return { jobs: jobs.map(presentJob_) };
}

/** Puts a failed job back in the queue. It carries on from the step that failed, so nothing is posted twice. */
function retry_(req) {
  const job = jobOrThrow_(req.id).job;
  if (job.status !== 'failed') throw new ApiError('invalid', `Only a failed job can be retried; this one is ${job.status}`);
  Object.assign(job, { status: 'queued', attempts: 0, notBefore: null, error: null });
  saveJob_(job);
  return { job: presentJob_(job) };
}

function cancel_(req) {
  const job = jobOrThrow_(req.id).job;
  if (job.status !== 'queued') throw new ApiError('invalid', `Only a queued job can be cancelled; this one is ${job.status}`);
  if (job.state && job.state.videoId) throw new ApiError('invalid', 'This job already uploaded its video; delete it on the platform instead');
  job.status = 'cancelled';
  saveJob_(job);
  return { job: presentJob_(job) };
}

// ---- src/deploy.js ----
/**
 * Pull deploy: keeps this script on the latest code from GitHub, with no credentials stored anywhere.
 * An hourly trigger (or the admin `deploy` action) fetches dist/Code.js and the manifest from the source
 * branch; if they changed, it replaces the project's code, makes a new version and points the web app at it.
 * The web app URL never changes. GitHub Actions calls `deploy` with the merged commit's SHA after every push
 * to main (.github/workflows/deploy.yml); the hourly run is the fallback if that call fails.
 */

function deployLatest() {
  console.log(JSON.stringify(deployLatest_(false)));
}

function deployLatest_(force, ref) {
  const p = props_();
  // A commit SHA pins the exact merged code; raw.githubusercontent.com can serve a branch a few minutes stale.
  if (ref && !/^[0-9a-f]{40}$/.test(String(ref))) throw new ApiError('invalid', 'ref must be a full 40-character commit SHA');
  // The repo was called social-manager before November 2026; the old name is tried if the new one is not found.
  const repos = p.getProperty('SOURCE_REPO') ? [p.getProperty('SOURCE_REPO')]
    : ['ravitejakamalapuram/social-media-publisher', 'ravitejakamalapuram/social-manager'];
  const branch = p.getProperty('SOURCE_BRANCH') || 'main';
  const at = ref || branch;
  const label = ref ? ref.slice(0, 7) : branch;
  const raw = (path) => {
    let code = 0;
    for (const repo of repos) {
      const r = UrlFetchApp.fetch(`https://raw.githubusercontent.com/${repo}/${at}/${path}`, { muteHttpExceptions: true });
      code = r.getResponseCode();
      if (code === 200) return r.getContentText();
      if (code !== 404) break;
    }
    throw new ApiError('upstream', `GitHub answered ${code} for ${path}`);
  };
  const code = raw('dist/Code.js');
  const manifest = raw('src/appsscript.json');
  const hash = sha256Hex_(code + manifest);
  // Right after a commit deploy, the branch URL may still serve the previous code; don't roll back to it.
  // Checked after the fetches (not before), so a commit deploy that finished while they ran is seen.
  // No script lock: the job queue uses it, and a deploy holding it would make publish calls busy.
  if (!ref && !force && Date.now() - Number(p.getProperty('REF_DEPLOYED_AT') || 0) < 15 * 60 * 1000) {
    return { deployed: false, reason: 'a commit was deployed in the last 15 minutes' };
  }
  if (!force && hash === p.getProperty('DEPLOYED_HASH')) {
    if (ref) p.setProperty('REF_DEPLOYED_AT', String(Date.now()));
    return { deployed: false, reason: 'already on the latest code' };
  }

  const api = `https://script.googleapis.com/v1/projects/${ScriptApp.getScriptId()}`;
  googleJson_('put', `${api}/content`, {
    json: { files: [{ name: 'Code', type: 'SERVER_JS', source: code }, { name: 'appsscript', type: 'JSON', source: manifest }] },
  });
  const version = googleJson_('post', `${api}/versions`, { json: { description: `${label} ${hash.slice(0, 7)}` } });
  const config = { scriptId: ScriptApp.getScriptId(), versionNumber: version.versionNumber, manifestFileName: 'appsscript', description: `${label} ${hash.slice(0, 7)}` };
  const web = (googleJson_('get', `${api}/deployments`).deployments || [])
    .find((d) => d.deploymentConfig && d.deploymentConfig.versionNumber && (d.entryPoints || []).some((e) => e.entryPointType === 'WEB_APP'));
  const dep = web
    ? googleJson_('put', `${api}/deployments/${web.deploymentId}`, { json: { deploymentConfig: config } })
    : googleJson_('post', `${api}/deployments`, { json: config });
  p.setProperty('DEPLOYED_HASH', hash);
  if (ref) p.setProperty('REF_DEPLOYED_AT', String(Date.now()));
  const entry = (dep.entryPoints || []).find((e) => e.entryPointType === 'WEB_APP');
  return { deployed: true, version: version.versionNumber, url: entry && entry.webApp ? entry.webApp.url : null };
}

// ---- src/setup.js ----
/**
 * One-time setup, run from the Apps Script editor (select setup, press Run). Safe to run again:
 * it reuses the spreadsheet, trigger and tokens that already exist.
 */

function setup() {
  const p = props_();
  let ss = null;
  const id = p.getProperty('SHEET_ID');
  if (id) {
    try { ss = SpreadsheetApp.openById(id); } catch (err) { ss = null; }
  }
  if (!ss) {
    ss = SpreadsheetApp.create('Social Media Publisher');
    p.setProperty('SHEET_ID', ss.getId());
  }
  let sh = ss.getSheetByName('Jobs');
  if (!sh) {
    sh = ss.getSheets()[0];
    sh.setName('Jobs');
  }
  sh.getRange(1, 1, 1, JOB_COLS.length).setValues([JOB_COLS]).setFontWeight('bold');
  sh.setFrozenRows(1);

  const handlers = ScriptApp.getProjectTriggers().map((t) => t.getHandlerFunction());
  if (!handlers.includes('runQueue')) ScriptApp.newTrigger('runQueue').timeBased().everyMinutes(5).create();
  if (!handlers.includes('deployLatest')) ScriptApp.newTrigger('deployLatest').timeBased().everyHours(1).create();

  const lines = [`Jobs sheet: ${ss.getUrl()}`];
  try {
    const c = YouTube.whoami();
    lines.push(`YouTube channel: ${c.title} (${c.url}). If this is not the channel you want, see the FAQ.`);
  } catch (err) {
    lines.push(`YouTube check failed: ${err.message}`);
  }
  [Instagram, Facebook].forEach((a) => {
    try { lines.push(`${a.name}: ${a.whoami().title}`); } catch (err) { lines.push(`${a.name}: ${err.message}`); }
  });
  if (!Object.values(tokens_()).some((t) => t.admin)) {
    lines.push(`Admin token (shown once, keep it in a password manager): ${issueToken_('admin', true)}`);
  } else {
    lines.push('Admin token already exists; run resetAdminToken() if you lost it.');
  }
  console.log(lines.join('\n'));
}

/** Replaces the admin token, e.g. if it leaked. Other tokens keep working. */
function resetAdminToken() {
  replaceToken_('admin', true);
}

/** Issues (or replaces) the token Claude's scheduled jobs use. */
function createTokenForClaude() {
  replaceToken_('claude', false);
}

/** Issues (or replaces) the admin token the GitHub deploy Action uses (secret PUBLISHER_ADMIN_TOKEN). */
function createTokenForGitHub() {
  replaceToken_('github-deploy', true);
}

function replaceToken_(name, admin) {
  const all = tokens_();
  Object.keys(all).forEach((h) => { if (all[h].name === name) delete all[h]; });
  props_().setProperty('TOKENS', JSON.stringify(all));
  console.log(`Token for "${name}" (shown once): ${issueToken_(name, admin)}`);
}
